with enriched as (select *, last_value(rating) ignore nulls over (partition by city order by rating, id rows between unbounded preceding and current row) as last_known_rating, max(rating) over (partition by city) as city_max_rating, row_number() over (order by rating desc, id) as seq_no from suppliers) select id, supplier_name, rating, city_max_rating, seq_no from enriched order by rating desc
